 * on the claim it was split off, so they are not judged on it again.
 */
private Claim changeStatus(String by, String sheetId, Long id, ClaimStatus next, String reason, boolean part,
        LocalDate on) {
    Claim claim = lockedClaim(sheetId, id);
    switch (next) {
        case OPEN -> settings.refuseUnlessMay(sheetId, by, "open");
        case SETTLED -> settings.refuseUnlessMay(sheetId, by, "settle");
        case VOID -> settings.refuseUnlessMay(sheetId, by, "void");
        default -> {
        }
    }
    RollupService.Snapshot before = rollup.snapshot(sheetId);
    String tail = "";
    // settling is the step from OPEN; a pending claim is settled by approving it
    if (!claim.getStatus().canMoveTo(next) || next == ClaimStatus.PENDING
            || (next == ClaimStatus.SETTLED && claim.getStatus() != ClaimStatus.OPEN)
            || (next == ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.DRAFT)) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A " + claim.getStatus() + " claim cannot become " + next + ".");
    }
    if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.load(sheetId).getToday())) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "The claim is deferred until " + claim.getDeferredUntil() + ".");
    }
    if (next == ClaimStatus.SETTLED && !part) {
        refuseFourEyes(by, claim);
    }
    if (next == ClaimStatus.DRAFT && claim.getCorrects() != null) {
        // a restored correction counts against its claim again
        refuseOverCorrection(sheetId, claim.getPersonId(), claim.getAmount(), claim.getCorrects(), claim.getId());
    }
    if (next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
        refuseVoidOfSettled(by, sheetId, claim);
        // the frozen figure leaves every total; the claim keeps its number and shows the figure it had
        tail = " reversed=" + text(claim.getSettledDue());
    }
    if (next == ClaimStatus.VOID) {
        String voidReason = voidReasons.refuseUnlessListed(sheetId, reason);
        claim.setVoidReason(voidReason);
        if (voidReason != null) {
            tail += " reason=" + voidReason;
        }
    }
    Person person = person(sheetId, claim.getPersonId());
    if (next == ClaimStatus.OPEN) {
        refuseFlaggedUnlessSteward(by, sheetId, person);
        refuseWithoutNote(sheetId, claim);
        refuseOverPeriodCap(sheetId, claim);
        if (aboveReviewThreshold(sheetId, person, claim)) {
            // it waits for a steward's review, and is numbered once it is reviewed
            next = ClaimStatus.REVIEW;
        } else {
            number(sheetId, claim);
        }
        claim.setOpenedBy(by);
    }
    String event = switch (next) {
        case OPEN -> "CLAIM_OPENED";
        case REVIEW -> "CLAIM_REVIEW";
        case SETTLED -> "CLAIM_SETTLED";
        case VOID -> "CLAIM_VOIDED";
        case DRAFT, PENDING, DELETED -> throw new IllegalStateException();
    };
    if (next == ClaimStatus.SETTLED) {
        // the due is fixed at the due a statement bound it to (late charge and floor included), else at the rate
        // the person's grade has in force on the claim's date, with the late charge it has gained by today, and
        // at least the floor in force on its date; with none it stays live
        BigDecimal fixed = on != null ? dueAsOf(sheetId, id, on)
                : claim.isStated() && claim.getStatedDue() != null ? claim.getStatedDue()
